import {
  forwardRef,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type HTMLAttributes,
  type ReactNode,
} from "react";

import { cn } from "@/lib/cn";
import {
  canAnimate,
  motionEasing,
  readMotion,
  useReducedMotion,
} from "@/lib/motion";

/**
 * The gap a vertical grid or flex container puts before this element, or 0
 * when it is the first child or its container doesn't stack.
 */
function stackGap(element: HTMLElement): number {
  const parent = element.parentElement;
  if (!parent || element.previousElementSibling === null) return 0;
  const style = getComputedStyle(parent);
  const stacks =
    style.display.includes("grid") ||
    (style.display.includes("flex") &&
      style.flexDirection.startsWith("column"));
  if (!stacks) return 0;
  const gap = Number.parseFloat(style.rowGap);
  return Number.isFinite(gap) ? gap : 0;
}

/** Props accepted by Presence. */
export type PresenceProps = {
  /** Whether the content is present. Leaving content stays mounted until it has left. */
  show: boolean;
  /** Animate the first mount too (for content that arrives after the page). */
  appear?: boolean;
  children: ReactNode;
} & HTMLAttributes<HTMLDivElement>;

/**
 * Content that arrives and leaves instead of popping: it makes room, fades in
 * while travelling the theme's `--stipe-motion-distance`, and on leaving fades
 * out and gives its room back before it unmounts. Reduced motion keeps a short
 * fade only.
 */
export const Presence = forwardRef<HTMLDivElement, PresenceProps>(
  function Presence(
    { show, appear = false, children, className, ...props },
    ref,
  ) {
    const node = useRef<HTMLDivElement>(null);
    useImperativeHandle<HTMLDivElement | null, HTMLDivElement | null>(
      ref,
      () => node.current,
    );
    const reduced = useReducedMotion();
    const [mounted, setMounted] = useState(show);
    const first = useRef(true);
    if (show && !mounted) setMounted(true);

    useLayoutEffect(() => {
      const element = node.current;
      const initial = first.current;
      first.current = false;
      if (!element || (initial && !appear)) return;
      if (!canAnimate(element)) {
        if (!show) setMounted(false);
        return;
      }
      const motion = readMotion(element);
      const travel = `translateY(${String(motion.distance)}px)`;
      const easing = motionEasing(motion, motion.ease);
      // In flow, arriving content makes room and leaving content gives it
      // back, so nothing below jumps. Reduced motion changes the room at once.
      const height = element.getBoundingClientRect().height;
      const gap = stackGap(element);
      const room = (from: number, to: number) => {
        element.style.overflow = "clip";
        const edge = (size: number) => ({
          height: `${String(size)}px`,
          marginBlockStart: `${String(size === 0 ? -gap : 0)}px`,
        });
        const animation = element.animate([edge(from), edge(to)], {
          duration: motion.normal,
          easing,
        });
        const restore = () => {
          element.style.removeProperty("overflow");
        };
        animation.addEventListener("finish", restore);
        animation.addEventListener("cancel", restore);
        return animation;
      };
      if (show) {
        const animations = [
          element.animate(
            [
              { opacity: 0, transform: travel },
              { opacity: 1, transform: "none" },
            ],
            { duration: motion.normal, easing },
          ),
        ];
        if (!reduced && height > 0) animations.push(room(0, height));
        return () => {
          for (const animation of animations) animation.cancel();
        };
      }
      const fade = element.animate(
        [
          { opacity: 1, transform: "none" },
          { opacity: 0, transform: travel },
        ],
        {
          duration: motion.fast,
          easing: motionEasing(motion, motion.easeExit),
          fill: "forwards",
        },
      );
      const last = !reduced && height > 0 ? room(height, 0) : fade;
      if (last !== fade) last.effect?.updateTiming({ fill: "forwards" });
      last.addEventListener("finish", () => {
        setMounted(false);
      });
      return () => {
        fade.cancel();
        last.cancel();
      };
    }, [show, appear, reduced]);

    if (!mounted) return null;
    return (
      <div
        {...props}
        ref={node}
        className={cn("caps-presence", className)}
        data-present={show}
        aria-hidden={show ? undefined : true}
      >
        {children}
      </div>
    );
  },
);

/** Props accepted by Collapse. */
export type CollapseProps = {
  /** Open: the content takes its height. Closed: no space, and out of the accessibility tree. */
  open: boolean;
  children: ReactNode;
} & HTMLAttributes<HTMLDivElement>;

/**
 * Content that opens and closes its own space: an inserted alert, a field
 * error, a disclosure body. Height and opacity follow the theme's tempo; under
 * reduced motion the space changes at once and only the fade remains.
 */
export const Collapse = forwardRef<HTMLDivElement, CollapseProps>(
  function Collapse({ open, children, className, ...props }, ref) {
    return (
      <div
        {...props}
        ref={ref}
        className={cn("caps-collapse", className)}
        data-open={open}
        aria-hidden={open ? undefined : true}
      >
        <div className="caps-collapse-clip">{children}</div>
      </div>
    );
  },
);

type Layer = Readonly<{ key: string; content: ReactNode }>;

/** Props accepted by Swap. */
export type SwapProps = {
  /** Names the current content. A new key crossfades from the old content to the new. */
  swapKey: string;
  /** Which edge leaving content holds to while the box resizes; `end` for right-aligned actions. */
  anchor?: "start" | "end";
  children: ReactNode;
} & HTMLAttributes<HTMLDivElement>;

/**
 * One piece of content replaced by another without a hard cut: loading to
 * loaded, "Saving…" to "Saved". The old content fades out (blurred by the
 * theme's `--stipe-motion-blur`) as the new one arrives, and the box eases to
 * the new size. Reduced motion keeps the crossfade and drops the travel.
 */
export const Swap = forwardRef<HTMLDivElement, SwapProps>(function Swap(
  { swapKey, anchor = "start", children, className, ...props },
  ref,
) {
  const node = useRef<HTMLDivElement>(null);
  useImperativeHandle<HTMLDivElement | null, HTMLDivElement | null>(
    ref,
    () => node.current,
  );
  const reduced = useReducedMotion();
  // The latest content rendered under the current key, kept so it can leave.
  const [shown, setShown] = useState<Layer>({
    key: swapKey,
    content: children,
  });
  const [leaving, setLeaving] = useState<readonly Layer[]>([]);
  if (shown.key !== swapKey) {
    setLeaving([
      ...leaving.filter(
        (layer) => layer.key !== swapKey && layer.key !== shown.key,
      ),
      shown,
    ]);
    setShown({ key: swapKey, content: children });
  } else if (shown.content !== children) {
    setShown({ key: swapKey, content: children });
  }
  const size = useRef<DOMRect | null>(null);

  useLayoutEffect(() => {
    const element = node.current;
    if (!element || !("ResizeObserver" in globalThis)) return;
    size.current = element.getBoundingClientRect();
    const observer = new ResizeObserver(() => {
      if (element.getAnimations().length === 0)
        size.current = element.getBoundingClientRect();
    });
    observer.observe(element);
    return () => {
      observer.disconnect();
    };
  }, []);

  useLayoutEffect(() => {
    const element = node.current;
    if (!element) return;
    const exits = [
      ...element.querySelectorAll<HTMLElement>(":scope > [data-swap-leaving]"),
    ];
    const entering = element.querySelector<HTMLElement>(
      ":scope > [data-swap-current]",
    );
    if (entering === null || exits.length === 0) return;
    if (!canAnimate(element)) {
      setLeaving([]);
      return;
    }
    const before = size.current;
    const after = element.getBoundingClientRect();
    const motion = readMotion(element);
    const animations = [
      entering.animate(
        [
          {
            opacity: 0,
            filter: `blur(${String(motion.blur)}px)`,
            transform: `translateY(${String(motion.distance / 2)}px)`,
          },
          { opacity: 1, filter: "blur(0px)", transform: "none" },
        ],
        {
          duration: motion.normal,
          easing: motionEasing(motion, motion.ease),
        },
      ),
    ];
    for (const layer of exits) {
      const exit = layer.animate(
        [
          { opacity: 1, filter: "blur(0px)", transform: "none" },
          {
            opacity: 0,
            filter: `blur(${String(motion.blur)}px)`,
            transform: `translateY(${String(-motion.distance / 2)}px)`,
          },
        ],
        {
          duration: motion.fast,
          easing: motionEasing(motion, motion.easeExit),
          fill: "forwards",
        },
      );
      const key = layer.dataset.swapLeaving;
      exit.onfinish = () => {
        setLeaving((layers) => layers.filter((layer) => layer.key !== key));
      };
      animations.push(exit);
    }
    const resized =
      before !== null &&
      (Math.abs(before.height - after.height) > 0.5 ||
        Math.abs(before.width - after.width) > 0.5);
    if (!reduced && resized)
      animations.push(
        element.animate(
          [
            {
              width: `${String(before.width)}px`,
              height: `${String(before.height)}px`,
            },
            {
              width: `${String(after.width)}px`,
              height: `${String(after.height)}px`,
            },
          ],
          {
            duration: motion.normal,
            easing: motionEasing(motion, motion.ease),
          },
        ),
      );
    return () => {
      for (const animation of animations) animation.cancel();
    };
  }, [swapKey, reduced]);

  return (
    <div
      {...props}
      ref={node}
      className={cn("caps-swap", className)}
      data-anchor={anchor}
    >
      {/* One keyed list, so a layer that starts leaving keeps its state. */}
      {[
        ...leaving.map((layer) => (
          <div
            key={layer.key}
            className="caps-swap-layer"
            data-swap-leaving={layer.key}
            aria-hidden="true"
          >
            {layer.content}
          </div>
        )),
        <div key={swapKey} className="caps-swap-layer" data-swap-current="">
          {children}
        </div>,
      ]}
    </div>
  );
});

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}
